70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /** Maximum number of owners a single city may contain; creating an owner in a city that
76	     *  already has this many owners is rejected with 409 Conflict. */
77	    private static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /** Maximum number of owners that may be created on a single day (by registration date); creating
80	     *  an owner once this many owners already carry today's registration date is rejected with
81	     *  429 Too Many Requests. */
82	    private static final int MAX_OWNERS_PER_DAY = 100;
83	
84	    /** When more than this many owners already carry today's registration date at creation time, the
85	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
86	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
87	
88	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
89	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    private final ClinicService clinicService;
97	
98	    private final OwnerMapper ownerMapper;
99	
100	    private final PetMapper petMapper;
101	
102	    private final VisitMapper visitMapper;
103	
104	    private final TelephoneNormalizer telephoneNormalizer;
105	
106	    private final HouseholdNormalizer householdNormalizer;
107	
108	    private final AddressNormalizer addressNormalizer;
109	
110	    private final EmailNormalizer emailNormalizer;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper,
116	                                 TelephoneNormalizer telephoneNormalizer,
117	                                 HouseholdNormalizer householdNormalizer,
118	                                 AddressNormalizer addressNormalizer,
119	                                 EmailNormalizer emailNormalizer) {
120	        this.clinicService = clinicService;
121	        this.ownerMapper = ownerMapper;
122	        this.petMapper = petMapper;
123	        this.visitMapper = visitMapper;
124	        this.telephoneNormalizer = telephoneNormalizer;
125	        this.householdNormalizer = householdNormalizer;
126	        this.addressNormalizer = addressNormalizer;
127	        this.emailNormalizer = emailNormalizer;
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
133	        Collection<Owner> owners;
134	        if (lastName != null) {
135	            owners = this.clinicService.findOwnerByLastName(lastName);
136	        } else {
137	            owners = this.clinicService.findAllOwners();
138	        }
139	        if (owners.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        return createOwner(ownerFieldsDto);
159	    }
160	
161	    /**
162	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
163	     * response for the newly persisted owner: the request fields are mapped and normalized, every
164	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
165	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
166	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
167	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
168	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
169	     * {@code addOwner} without disturbing the creation steps gathered here.
170	     *
171	     * @param ownerFieldsDto the submitted owner fields
172	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
173	     */
174	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
175	        HttpHeaders headers = new HttpHeaders();
176	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
177	        normalizeOwnerFields(owner);
178	        // Enforce the pre-persistence policies that can reject the new owner outright.
179	        rejectDisallowedOwnerCreation(owner);
180	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
181	        // function of last name and postcode), reject a household duplicate unless the request
182	        // declares it shares the household, and record the household size. This runs before the
183	        // identity-key check so that check sees the owner's household id.
184	        boolean declaredHouseholdMember =
185	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
186	        // Reject the create when the owner's whole derived identity key (normalized telephone,
187	        // email and household id) already matches an existing owner. This single rule subsumes the
188	        // former separate telephone, email and household duplicate checks.
189	        rejectWhenIdentityInUse(owner);
190	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
191	        // shares an existing owner's last name and postcode with a different telephone. A declared
192	        // household member is never flagged: it is a known member, not a suspected duplicate.
193	        assignPossibleDuplicate(owner, declaredHouseholdMember);
194	        // Assign the remaining create-time derived fields (namesake count, customer code,
195	        // membership number and bulk-signup warning), each fixed at creation time.
196	        assignDerivedFields(owner);
197	        this.clinicService.saveOwner(owner);
198	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
199	        // Emit an audit line for the successful create, carrying the owner id, customer code,
200	        // registration date, membership level and membership number so the create can be traced
201	        // from the dedicated AUDIT log.
202	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
203	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
204	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
205	        headers.setLocation(UriComponentsBuilder.newInstance()
206	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
207	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    /**
211	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
212	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
213	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
214	     * the sequence of create-time rejections stays readable and a new rule is added as one more
215	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
216	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
217	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
218	     * the household id has been resolved, because that key includes the household id.
219	     *
220	     * @param owner the newly mapped and normalized owner being created
221	     */
222	    private void rejectDisallowedOwnerCreation(Owner owner) {
223	        rejectWhenDailyLimitReached(owner);
224	        rejectWhenCityAtCapacity(owner);
225	    }
226	
227	    /**
228	     * Applies the household-membership rules for a newly normalized owner being created. The
229	     * household id is a deterministic function of the owner's last name and postcode, so owners
230	     * with the same last name and postcode share it automatically; it is assigned to the new owner
231	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
232	     * same last name and postcode is a member of the same household: a second such owner is rejected
233	     * as a household duplicate (409) unless the request declares it shares the household via
234	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
235	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
236	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
237	     * is resolved here before {@link #rejectWhenIdentityInUse}.
238	     *
239	     * @param owner           the newly mapped and normalized owner being created
240	     * @param sharesHousehold whether the request declared that the owner shares an existing household
241	     * @return {@code true} if the owner joined an existing household as a declared member
242	     */
243	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
244	        // Assign the deterministic household id (a pure function of last name and postcode) so every
245	        // owner with the same last name and postcode shares it automatically.
246	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
247	        // Identify any existing owners in the same household (same computed household id).
248	        List<Owner> householdMembers = sameHouseholdOwners(owner);
249	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
250	        // the request declares it shares the household, in which case create it as a declared member.
251	        boolean declaredHouseholdMember = false;
252	        if (!householdMembers.isEmpty()) {
253	            if (!sharesHousehold) {
254	                throw new HouseholdDuplicateException(
255	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
256	            }
257	            declaredHouseholdMember = true;
258	        }
259	        // Record the size of this owner's household after this create, fixed at creation time.
260	        owner.setHouseholdSize(householdMembers.size() + 1);
261	        return declaredHouseholdMember;
262	    }
263	
264	    /**
265	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
266	     * has already been resolved: the namesake count, the per-city customer code, the membership
267	     * number derived from that customer code and the registration fiscal year, and the bulk-signup warning
268	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
269	     * here keeps {@link #addOwner} focused on the high-level create sequence.
270	     *
271	     * @param owner the owner being created, already normalized and with its household resolved
272	     */
273	    private void assignDerivedFields(Owner owner) {
274	        // Record how many existing owners already share this owner's first and last name
275	        // (compared case-insensitively) before this create, fixed at creation time.
276	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
277	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
278	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
279	        // time.
280	        owner.setCustomerCode(customerCode(owner));
281	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
282	        // of the fiscal year of the registration date (e.g. 'NSW-A1B2C3D4-M26'), fixed at
283	        // creation time.
284	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
285	        // Flag the create when more than 80 owners have already been created on this owner's
286	        // (adjusted business-day) registration date, fixed at creation time.
287	        owner.setBulkSignupWarning(
288	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
289	    }
290	
291	    /**
292	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
293	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
294	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
295	     * the former separate telephone, email and household duplicate checks: two owners collide only
296	     * when their whole keys are equal, and members of one household with different telephones have
297	     * different keys and are both allowed.
298	     *
299	     * @param owner the owner being created, already normalized and with its household resolved
300	     */
301	    private void rejectWhenIdentityInUse(Owner owner) {
302	        String identityKey = owner.getIdentityKey();
303	        boolean inUse = existingOwners()
304	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
305	        if (inUse) {
306	            throw new DuplicateIdentityException(
307	                "An owner with identity key " + identityKey + " already exists");
308	        }
309	    }
310	
311	    /**
312	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
313	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
314	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
315	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
316	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
317	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
318	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
319	     * possible duplicate. A declared household member is never flagged: it is a known member of the
320	     * household, not a suspected duplicate. Both values are fixed at creation time.
321	     *
322	     * @param owner                   the owner being created, already normalized and confirmed not a
323	     *                                hard duplicate
324	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
325	     *                                member
326	     */
327	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
328	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
329	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
330	            .map(Owner::getId)
331	            .min(Integer::compareTo)
332	            .orElse(null);
333	        owner.setPossibleDuplicate(matchId != null);
334	        owner.setPossibleDuplicateOf(matchId);
335	    }
336	
337	    /**
338	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
339	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
340	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
341	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
342	     *
343	     * @param existing an existing owner to compare against
344	     * @param owner    the owner being created
345	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
346	     */
347	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
348	        return existing.getPostcode() != null
349	            && existing.getPostcode().equals(owner.getPostcode())
350	            && existing.getLastName() != null
351	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
352	            && existing.getTelephone() != null
353	            && !existing.getTelephone().equals(owner.getTelephone());
354	    }
355	
356	    /**
357	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
358	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
359	     *
360	     * @param owner the owner being created
361	     */
362	    private void rejectWhenDailyLimitReached(Owner owner) {
363	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
364	            throw new DailyOwnerLimitExceededException(
365	                "The maximum number of owners that may be created today has already been reached");
366	        }
367	    }
368	
369	    /**
370	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
371	     * or more owners, with 409 Conflict.
372	     *
373	     * @param owner the owner being created
374	     */
375	    private void rejectWhenCityAtCapacity(Owner owner) {
376	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
377	            throw new CityCapacityExceededException(
378	                "The city " + owner.getCity() + " already contains the maximum number of owners");
379	        }
380	    }
381	
382	    /**
383	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
384	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
385	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
386	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
387	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
388	     * server's current date. Canonicalising the address here, before the household checks read it,
389	     * ensures duplicate detection and the shared household id both compare the normalized form.
390	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
391	     * duplicate, household and customer-code rules.
392	     *
393	     * @param owner the newly mapped owner to canonicalize
394	     */
395	    private void normalizeOwnerFields(Owner owner) {
396	        // Canonicalize the owner's address fields on create so the address is stored and returned in
397	        // canonical form and every later comparison (household duplicate detection and the shared
398	        // household id) uses it. A value that is blank after normalization is rejected with 400.
399	        normalizeAddressFields(owner);
400	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
401	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
402	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
403	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
404	        // Store the (already syntactically validated) email lower-cased so it is persisted and
405	        // returned in canonical form. A missing email is left untouched.
406	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
407	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
408	        // canonicalization so the comparison sees the lower-cased value.
409	        rejectDisposableEmailDomain(owner.getEmail());
410	        // Validate the optional postcode against the fixed range for the city's region. A postcode
411	        // is checked only when present (it is optional); one out of range for the city's region is
412	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
413	        // value is left unchanged.
414	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
415	        // Reject a supplied registration date that is later than the server's current date with
416	        // 400, before any defaulting or business-day adjustment, so a future date is never
417	        // persisted regardless of how the roll-forward would move it.
418	        rejectFutureRegistrationDate(owner.getRegistrationDate());
419	        // Default the registration date to the server's current date when the client did not
420	        // supply one, then roll the effective date forward to a business day so a Saturday or
421	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
422	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
423	        // date-derived field (such as the membership number's year segment) and the per-day
424	        // create-limit are computed from.
425	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
426	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
427	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
428	    }
429	
430	    /**
431	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
432	     * returned in canonical form. The owner may supply its address in either of two forms and the
433	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
434	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
435	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
436	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
437	     * stored {@code address} is composed from the normalized structured lines when present — the
438	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
439	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
440	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
441	     * here, before the household checks read it, ensures duplicate detection and the shared household
442	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
443	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
444	     *
445	     * @param owner the newly mapped owner whose address is canonicalized
446	     */
447	    private void normalizeAddressFields(Owner owner) {
448	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
449	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
450	            owner.setAddressLine1(line1);
451	            String composed = line1;
452	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
453	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
454	                owner.setAddressLine2(line2);
455	                composed = line1 + " " + line2;
456	            }
457	            owner.setAddress(composed);
458	        }
459	        else {
460	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
461	        }
462	    }
463	
464	    /**
465	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
466	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
467	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
468	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
469	     * domain part is left untouched.
470	     *
471	     * @param email the owner's canonicalized email, or {@code null} when absent
472	     */
473	    private void rejectDisposableEmailDomain(String email) {
474	        if (email == null) {
475	            return;
476	        }
477	        int at = email.lastIndexOf('@');
478	        if (at < 0) {
479	            return;
480	        }
481	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
482	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
483	            throw new DisposableEmailException(
484	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
485	        }
486	    }
487	
488	    /**
489	     * Rejects a supplied registration date that is later than the server's current date with a
490	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
491	     * accepted, and a date on or before today is left for the normal defaulting and business-day
492	     * adjustment.
493	     *
494	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
495	     */
496	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
497	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
498	            throw new InvalidRegistrationDateException(
499	                "The supplied registration date " + registrationDate + " is later than the current date");
500	        }
501	    }
502	
503	    /**
504	     * The fixed list of public holidays. A registration date that lands on one of these dates is
505	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
506	     */
507	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
508	        java.time.LocalDate.of(2026, 1, 1),
509	        java.time.LocalDate.of(2026, 1, 26),
510	        java.time.LocalDate.of(2026, 4, 25),
511	        java.time.LocalDate.of(2026, 12, 25),
512	        java.time.LocalDate.of(2026, 12, 28));
513	
514	    /**
515	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
516	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
517	     * unchanged. Applied to the effective registration date (whether supplied in the request or
518	     * defaulted to the server date) so the persisted registration date, every value derived from it
519	     * and the per-day create-limit all use the adjusted business day.
520	     *
521	     * @param date the effective registration date
522	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
523	     */
524	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
525	        java.time.LocalDate adjusted = date;
526	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
527	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
528	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
529	            adjusted = adjusted.plusDays(1);
530	        }
531	        return adjusted;
532	    }
533	
534	    /**
535	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
536	     * region derived from the owner's postcode (falling back to the city, via
537	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
538	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
539	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
540	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
541	     * distinct customer codes.
542	     *
543	     * @param owner the owner being created, already normalized
544	     * @return the formatted, de-duplicated customer code
545	     */
546	    private String customerCode(Owner owner) {
547	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
548	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
549	        String base = region + "-" + hash8;
550	        Set<String> taken = existingOwners()
551	            .map(Owner::getCustomerCode)
552	            .filter(code -> code != null)
553	            .collect(Collectors.toSet());
554	        if (!taken.contains(base)) {
555	            return base;
556	        }
557	        int n = 2;
558	        while (taken.contains(base + "-" + n)) {
559	            n++;
560	        }
561	        return base + "-" + n;
562	    }
563	
564	    /**
565	     * Streams the existing owners that the create-time rules match a new owner against. Every
566	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
567	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
568	     * own matching criterion rather than on how the existing owners are retrieved.
569	     *
570	     * @return a stream over all existing owners
571	     */
572	    private Stream<Owner> existingOwners() {
573	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
574	        // new create, so the duplicate, identity and household checks (and the other create-time
575	        // scans built on this helper) ignore it.
576	        return this.clinicService.findAllOwners().stream()
577	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
578	    }
579	
580	    /**
581	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
582	     * fix the per-city sequence of an owner's customer code at creation time.
583	     *
584	     * @param city the city of the owner being created
585	     * @return the number of existing owners in a matching city
586	     */
587	    private int countOwnersInCity(String city) {
588	        return (int) existingOwners()
589	            .filter(existing -> existing.getCity() != null
590	                && existing.getCity().equalsIgnoreCase(city))
591	            .count();
592	    }
593	
594	    /**
595	     * Counts the existing owners whose registration date is the given adjusted business day. Used
596	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
597	     * owners already carry that business day as their registration date.
598	     *
599	     * @param date the adjusted business-day registration date to match
600	     * @return the number of existing owners registered on that date
601	     */
602	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
603	        return (int) existingOwners()
604	            .filter(existing -> date.equals(existing.getRegistrationDate()))
605	            .count();
606	    }
607	
608	    /**
609	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
610	     * the last two digits of the fiscal year of the (business-day-adjusted) registration date
611	     * (e.g. 'NSW-A1B2C3D4-M26'). The fiscal year starts on 1 July, so a registration date on or
612	     * after 1 July carries the following calendar year's fiscal year.
613	     *
614	     * @param customerCode     the owner's customer code
615	     * @param registrationDate the owner's registration date
616	     * @return the formatted membership number
617	     */
618	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
619	        return String.format("%s-M%02d",
620	            customerCode, org.springframework.samples.petclinic.util.FiscalYear.of(registrationDate) % 100);
621	    }
622	
623	    /**
624	     * Returns the existing owners in the given owner's household, i.e. those sharing its
625	     * deterministic household id (the same last name and postcode). The id is computed via
626	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
627	     * whitespace are treated as the same household. Centralising how "the same household" is matched
628	     * here keeps that definition in one place for every caller.
629	     *
630	     * @param owner the owner being created, with its household id already assigned
631	     * @return the existing owners in the owner's household (possibly empty)
632	     */
633	    private List<Owner> sameHouseholdOwners(Owner owner) {
634	        String householdId = owner.getHouseholdId();
635	        return existingOwners()
636	            .filter(existing -> householdId.equals(
637	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
638	            .toList();
639	    }
640	
641	    /**
642	     * Counts the existing owners who share the given first and last name, compared
643	     * case-insensitively. Used to fix an owner's namesake count at creation time.
644	     *
645	     * @param firstName the first name of the owner being created
646	     * @param lastName  the last name of the owner being created
647	     * @return the number of existing owners with a matching first and last name
648	     */
649	    private int countNamesakes(String firstName, String lastName) {
650	        return (int) existingOwners()
651	            .filter(existing -> existing.getFirstName() != null
652	                && existing.getFirstName().equalsIgnoreCase(firstName)
653	                && existing.getLastName() != null
654	                && existing.getLastName().equalsIgnoreCase(lastName))
655	            .count();
656	    }
657	
658	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
659	    @Override
660	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
661	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
662	        if (currentOwner == null) {
663	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
664	        }
665	        currentOwner.setAddress(ownerFieldsDto.getAddress());
666	        currentOwner.setCity(ownerFieldsDto.getCity());
667	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
668	        currentOwner.setLastName(ownerFieldsDto.getLastName());
669	        // Normalize the telephone to canonical E.164 form so it is stored and returned
670	        // consistently with create; an unformattable value is rejected with 400.
671	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
672	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
673	        this.clinicService.saveOwner(currentOwner);
674	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
675	    }
676	
677	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
678	    @Transactional
679	    @Override
680	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
681	        Owner owner = this.clinicService.findOwnerById(ownerId);
682	        if (owner == null) {
683	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
684	        }
685	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
686	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
687	        // duplicate and identity checks (see existingOwners()).
688	        owner.setDeleted(true);
689	        this.clinicService.saveOwner(owner);
690	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
691	    }
692	
693	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
694	    @Override
695	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
696	        Owner owner = this.clinicService.findOwnerById(ownerId);
697	        if (owner == null) {
698	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
699	        }
700	        HttpHeaders headers = new HttpHeaders();
701	        Pet pet = petMapper.toPet(petFieldsDto);
702	        owner.setId(ownerId);
703	        pet.setOwner(owner);
704	        pet.getType().setName(null);
705	        this.clinicService.savePet(pet);
706	        PetDto petDto = petMapper.toPetDto(pet);
707	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
708	            .buildAndExpand(pet.getId()).toUri());
709	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
710	    }
711	
712	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
713	    @Override
714	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
715	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
716	        if (currentOwner != null) {
717	            Pet currentPet = this.clinicService.findPetById(petId);
718	            if (currentPet != null) {
719	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
720	                currentPet.setName(petFieldsDto.getName());
721	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
722	                this.clinicService.savePet(currentPet);
723	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
724	            }
725	        }
726	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
727	    }
728	
729	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
730	    @Override
731	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
732	        HttpHeaders headers = new HttpHeaders();
733	        Visit visit = visitMapper.toVisit(visitFieldsDto);
734	        Pet pet = new Pet();
735	        pet.setId(petId);
736	        visit.setPet(pet);
737	        this.clinicService.saveVisit(visit);
738	        VisitDto visitDto = visitMapper.toVisitDto(visit);
739	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
740	            .buildAndExpand(visit.getId()).toUri());
741	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
742	    }
743	
744	
745	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
746	    @Override
747	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
748	        Owner owner = this.clinicService.findOwnerById(ownerId);
749	        if (owner != null) {
750	            Pet pet = owner.getPet(petId);
751	            if (pet != null) {
752	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
753	            }
754	        }
755	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
756	    }
757	}
