@PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
@Override
public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
    // Idempotent create: when the request carries an 'Idempotency-Key' header that has already
    // been used for a successful create, return the originally created owner with 200 OK instead
    // of running the create pipeline again (which would otherwise reject the repeat as a duplicate
    // with 409). A first, unseen key runs the normal create and records its result under the key.
    String idempotencyKey = currentIdempotencyKey();
    if (idempotencyKey == null || idempotencyKey.isBlank()) {
        return createOwner(ownerFieldsDto);
    }
    OwnerDto previouslyCreated = idempotentCreates.get(idempotencyKey);
    if (previouslyCreated != null) {
        return new ResponseEntity<>(previouslyCreated, HttpStatus.OK);
    }
    ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
    idempotentCreates.put(idempotencyKey, response.getBody());
    return response;
}

/**
 * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
 * the request carries no such header (or there is no active servlet request). Reading it from the
 * request context here keeps the header — a request-level concern surrounding the create — out of
 * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
 *
 * @return the {@code Idempotency-Key} header value, or {@code null} when absent
 */
private String currentIdempotencyKey() {
    RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
    if (attributes instanceof ServletRequestAttributes servletAttributes) {
        return servletAttributes.getRequest().getHeader("Idempotency-Key");
    }
    return null;
}

